ready.text:
[!Note]
　　在初始化完成后发布。
　　Hexo 启动时会触发。
hexo.on('ready', () => {
 hexo.log.info('Hello world!')
})

new.text:
[!Note]
　　在文章文件建立后发布。 该事件返回文章参数。
hexo.on("new", function (post) {
 console.log(`New post created:\n${post.content}\n${post.path}`);
});
　　当执行命令 hexo new 时会触发：
hexo new test
INFO Validating config
New post created:
---
title: test
date: 2024

exit.text:
[!Note]
　　在 Hexo 结束前发布。
hexo.on("exit", function () {
 console.log('Bye!');
});

